import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";

import {SwimlaneComponent} from "./swimlane.component";
import {SWIMLANE_ACTION, SWIMLANE_CARD} from "./swimlane.types";

export * from "./swimlane.types";
export * from "./swimlane.model";

registerCardComponent({
  name: SWIMLANE_CARD,
  component: SwimlaneComponent,
  events: actionTypesToEvents(SWIMLANE_ACTION),
});

import React, {memo, useEffect, useId, useLayoutEffect, useMemo, useRef, useState} from "react";
import type {PiCardProps} from "@pihanga2/core";
import clsx from "clsx";

import {
  DEF_GUTTER_WIDTH,
  DEF_HEADER_HEIGHT,
  DEF_LANE_WIDTH,
  DEF_ROW_HEIGHT,
  type SwimlaneEvents,
  type SwimlaneGhostRow,
  type SwimlaneLanesSnapshot,
  type SwimlaneModel,
  type SwimlaneProps,
  type SwimlaneRow,
  type SwimlaneRowId,
  type SwimlaneTarget,
  type SwimlaneTargetKind,
} from "./swimlane.types";
import {
  describeSwimlaneTarget,
  formatTs,
  projectPending,
  relatedCallIds,
  rowTouches,
  stepKeyOf,
  stepRows,
} from "./swimlane.model";

import "./swimlane.css";

/**
 * Real-time swimlane (sequence) diagram.
 *
 * Every transition is its own small, fixed-height SVG in normal document flow,
 * so the page (or nearest scroll container) scrolls — the SVGs never do.
 * Each row draws its top half from the `pre` lane snapshot and its bottom half
 * from `post`, which lets lifelines start, activities open/close and run
 * states change in the middle of a row.
 *
 * Hover/click use one delegated listener on the rows container; hit zones are
 * wide transparent shapes carrying `data-*` attributes.
 */

type Geo = {laneW: number; rowH: number; gutter: number; mid: number; mk: string};

const laneX = (g: Geo, i: number) => g.gutter + i * g.laneW + g.laneW / 2;

// ─────────────────────────────────────────────────────────────────────────────
// Drawing helpers
// ─────────────────────────────────────────────────────────────────────────────

type Parts = {visuals: React.ReactNode[]; hits: React.ReactNode[]};

function drawLanes(
  p: Parts,
  g: Geo,
  laneOrder: string[],
  pre: SwimlaneLanesSnapshot,
  post: SwimlaneLanesSnapshot,
  hl: string | null,
  laneLabels: Record<string, string>,
  /** Activity of the process that sends/receives the hovered transition. */
  proc: string | null = null,
  /** Per-lane extra class for the activity bar (`SwimlaneLaneEvent.activityClassName`). */
  laneActivityClassName: Record<string, string> = {},
  /** Per-lane inline style for the activity bar (`SwimlaneLaneEvent.activityStyle`). */
  laneActivityStyle: Record<string, React.CSSProperties> = {},
) {
  laneOrder.forEach((l, i) => {
    const x = laneX(g, i);
    const halves: [SwimlaneLanesSnapshot, number, number][] = [
      [pre, 0, g.mid],
      [post, g.mid, g.rowH],
    ];
    halves.forEach(([snap, y1, y2], half) => {
      const s = snap[l];
      if (!s) return;
      p.visuals.push(
        <line key={`ll-${l}-${half}`} className={`swl-ll swl-ll-${s.state}`} x1={x} x2={x} y1={y1} y2={y2} />,
      );
      s.acts.forEach((a, k) => {
        const ax = x - 5 + k * 5;
        // fill + side borders only, so stacked half-row segments read as one
        // bar; caps only where the activity starts / ends inside this row
        const starts = half === 1 && !pre[l]?.acts.includes(a);
        const ends = half === 0 && !post[l]?.acts.includes(a);
        const d =
          `M${ax},${y1} V${y2} M${ax + 10},${y1} V${y2}` +
          (starts ? ` M${ax},${y1} H${ax + 10}` : "") +
          (ends ? ` M${ax},${y2} H${ax + 10}` : "");
        // `activityStyle` is applied to both the rect (normally filled, not
        // stroked) and the path (normally stroked, not filled) — set `fill`
        // for the bar's background and `stroke` for its border; the same
        // object on both elements is harmless since each only renders with
        // the properties it has a value for.
        const actStyle = laneActivityStyle[l];
        p.visuals.push(
          <g
            key={`a-${a}-${half}`}
            className={clsx(
              "swl-act",
              laneActivityClassName[l],
              hl === a ? "swl-hl" : proc === a && "swl-hl-proc",
            )}
          >
            <rect x={ax} y={y1} width={10} height={y2 - y1} style={actStyle} />
            <path d={d} style={actStyle} />
          </g>,
        );
        p.hits.push(
          <rect
            key={`ha-${a}-${half}`}
            className="swl-hit"
            x={ax - 8}
            y={y1}
            width={26}
            height={y2 - y1}
            data-kind="activity"
            data-id={a}
            data-lane={l}
          />,
        );
      });
    });
    if (!pre[l] && post[l]) {
      p.visuals.push(
        <rect key={`h-${l}`} className="swl-lane-head" x={x - 16} y={g.mid - 5} width={32} height={10} rx={2} />,
        <text key={`ht-${l}`} className="swl-lbl-muted" x={x + 20} y={g.mid + 3}>
          + {laneLabels[l] ?? l} joined
        </text>,
      );
    }
  });
}

function drawArrow(
  p: Parts,
  g: Geo,
  idx: (l: string) => number,
  a: {
    from: string;
    to: string;
    cls: string;
    marker: string;
    label: string;
    hitId: string;
    kind: SwimlaneTargetKind;
    rowId?: SwimlaneRowId;
    hl: boolean;
    /** Secondary highlight: a transition created/received by the hovered process. */
    rel?: boolean;
  },
) {
  const i1 = idx(a.from);
  const i2 = idx(a.to);
  if (i1 < 0 || i2 < 0) return;
  const x1 = laneX(g, i1);
  const x2 = laneX(g, i2);
  const cls = clsx("swl-ar", a.cls, a.hl ? "swl-hl" : a.rel && "swl-hl-rel");
  const markerEnd = `url(#${g.mk}-${a.marker})`;
  const hitData = {"data-kind": a.kind, "data-id": a.hitId, "data-row": a.rowId};
  if (a.from === a.to) {
    const d = `M${x1 + 6},${g.mid - 9} h26 v16 h-20`;
    p.visuals.push(
      <path key="ar" className={cls} d={d} markerEnd={markerEnd} />,
      <text key="lb" className="swl-lbl" x={x1 + 38} y={g.mid + 3}>
        {a.label}
      </text>,
    );
    p.hits.push(<path key="hit" className="swl-hit" d={d} strokeWidth={14} pointerEvents="stroke" {...hitData} />);
    return;
  }
  const dir = Math.sign(x2 - x1);
  const sx = x1 + dir * 6;
  const ex = x2 - dir * 6;
  p.visuals.push(
    <line key="ar" className={cls} x1={sx} x2={ex} y1={g.mid} y2={g.mid} markerEnd={markerEnd} />,
    <text key="lb" className="swl-lbl" x={Math.min(sx, ex) + 8} y={g.mid - 5}>
      {a.label}
    </text>,
  );
  // broad hit zone: a 16px thick invisible band over the thin line
  p.hits.push(
    <line
      key="hit"
      className="swl-hit"
      x1={sx}
      x2={ex}
      y1={g.mid}
      y2={g.mid}
      strokeWidth={16}
      pointerEvents="stroke"
      {...hitData}
    />,
  );
}

const CALL_STYLE = {
  sync: ["swl-ar-sync", "sync"],
  async: ["swl-ar-async", "async"],
  event: ["swl-ar-event", "event"],
} as const;

// ─────────────────────────────────────────────────────────────────────────────
// Rows
// ─────────────────────────────────────────────────────────────────────────────

type RowCommon = {
  g: Geo;
  laneOrder: string[];
  laneLabels: Record<string, string>;
  /** Per-lane extra class for the activity bar (`SwimlaneLaneEvent.activityClassName`). */
  laneActivityClassName: Record<string, string>;
  /** Per-lane inline style for the activity bar (`SwimlaneLaneEvent.activityStyle`). */
  laneActivityStyle: Record<string, React.CSSProperties>;
  width: number;
  hl: string | null;
  /** True when this row's transition belongs to a child of the highlighted call. */
  rel?: boolean;
  /** Call id of the process (activity) that sends/receives the hovered transition. */
  proc?: string | null;
  /** Formats the timestamp column. Defaults to local wall-clock time. */
  fmtTs: (ts: number) => string;
};

const RealRow = memo(function RealRow({
  row, g, laneOrder, laneLabels, laneActivityClassName, laneActivityStyle, width, hl, rel, proc, fmtTs, grouped, stepHl,
}: RowCommon & {
  row: SwimlaneRow;
  /** Shares `step` with the previous row: draw a tie mark instead of a timestamp. */
  grouped?: boolean;
  /** This row's step is the hovered/clicked/highlighted one. */
  stepHl?: boolean;
}) {
  const p: Parts = {visuals: [], hits: []};
  const idx = (l: string) => laneOrder.indexOf(l);
  drawLanes(p, g, laneOrder, row.pre, row.post, hl, laneLabels, proc, laneActivityClassName, laneActivityStyle);
  const ev = row.event;
  switch (ev.type) {
    case "call": {
      const [cls, marker] = CALL_STYLE[ev.kind];
      drawArrow(p, g, idx, {
        from: ev.from, to: ev.to, cls, marker, label: ev.label,
        hitId: ev.id, kind: "transition", rowId: row.id, hl: hl === ev.id, rel,
      });
      break;
    }
    case "reply":
      if (row.route) {
        drawArrow(p, g, idx, {
          from: row.route.to, to: row.route.from,
          cls: ev.ok ? "swl-ar-reply" : "swl-ar-error", marker: ev.ok ? "reply" : "error",
          label: ev.label, hitId: ev.id, kind: "transition", rowId: row.id, hl: hl === ev.id, rel,
        });
      }
      break;
    case "done":
      if (row.route) {
        p.visuals.push(
          <text key="dn" className="swl-lbl-muted" x={laneX(g, idx(row.route.to)) + 14} y={g.mid + 3}>
            ✓ processed {row.route.label}
          </text>,
        );
      }
      break;
    case "state": {
      const x = laneX(g, idx(ev.lane));
      p.visuals.push(<circle key="st" cx={x} cy={g.mid} r={5} className={`swl-dot-${ev.state}`} />);
      if (ev.showLabel ?? true) {
        p.visuals.push(
          <text key="stl" className="swl-lbl-muted" x={x + 10} y={g.mid + 3}>
            → {ev.state}
          </text>,
        );
      }
      p.hits.push(
        <circle
          key="sth"
          className="swl-hit"
          cx={x}
          cy={g.mid}
          r={12}
          data-kind="state"
          data-id={`state-${row.id}`}
          data-lane={ev.lane}
          data-row={row.id}
        />,
      );
      break;
    }
  }
  return (
    <svg
      className={clsx("swl-row", row.fulfilled && "swl-arrived", grouped && "swl-grouped", stepHl && "swl-hl-step")}
      width={width}
      height={g.rowH}
      data-row={row.id}
    >
      {grouped ? (
        <line className="swl-ts-tie" x1={6} x2={6} y1={0} y2={g.rowH} />
      ) : (
        <text className="swl-ts" x={0} y={g.mid + 3}>
          {fmtTs(ev.ts)}
        </text>
      )}
      {row.fulfilled && (() => {
        const isError = ev.type === "reply" && ev.ok === false;
        return (
          <text className={clsx("swl-ok", isError && "swl-ok-error")} x={g.gutter - 16} y={g.mid + 4}>
            <title>{isError ? "replaced an outstanding message (error)" : "replaced an outstanding message"}</title>
            {isError ? "✗" : "✓"}
          </text>
        );
      })()}
      {p.visuals}
      <rect
        className="swl-hit"
        x={0}
        y={0}
        width={g.gutter - 2}
        height={g.rowH}
        data-kind="step"
        data-id={stepKeyOf(row)}
        data-row={row.id}
      />
      {p.hits}
    </svg>
  );
});

const DEF_FORMAT_WAIT = (ms: number) => `${(ms / 1000).toFixed(1)}s`;

const GhostRow = memo(function GhostRow({
  row, g, laneOrder, laneLabels, laneActivityClassName, laneActivityStyle, width, hl, rel, proc, now,
  formatWait = DEF_FORMAT_WAIT,
}: RowCommon & {row: SwimlaneGhostRow; now: number; formatWait?: (ms: number) => string}) {
  const p: Parts = {visuals: [], hits: []};
  const pd = row.pending;
  const waited = now - pd.since;
  const overdue = pd.timeoutMs != null && waited > pd.timeoutMs;
  drawLanes(p, g, laneOrder, row.pre, row.post, hl, laneLabels, proc, laneActivityClassName, laneActivityStyle);
  drawArrow(p, g, (l) => laneOrder.indexOf(l), {
    from: pd.from, to: pd.to, cls: clsx("swl-ar-ghost", overdue && "swl-overdue"), marker: "ghost",
    label: `⌛ ${pd.label}`, hitId: pd.id, kind: "pending", hl: hl === pd.id, rel,
  });
  return (
    <svg className="swl-row swl-ghost" width={width} height={g.rowH}>
      <text className={clsx("swl-ts", overdue && "swl-overdue")} x={0} y={g.mid + 3}>
        waiting {formatWait(waited)}
      </text>
      {p.visuals}
      {p.hits}
    </svg>
  );
});

const NowRow = memo(function NowRow({
  snap, count, g, laneOrder, laneLabels, laneActivityClassName, laneActivityStyle, width, proc,
}: Omit<RowCommon, "hl" | "rel"> & {snap: SwimlaneLanesSnapshot; count: number}) {
  const p: Parts = {visuals: [], hits: []};
  drawLanes(p, g, laneOrder, snap, snap, null, laneLabels, proc, laneActivityClassName, laneActivityStyle);
  return (
    <svg className="swl-row swl-now" width={width} height={g.rowH}>
      <text className="swl-now-lbl" x={0} y={g.mid + 3}>now</text>
      {p.visuals}
      <line className="swl-now-line" x1={g.gutter - 6} x2={width - 10} y1={g.mid} y2={g.mid} />
      <text className="swl-now-lbl" x={width - 136} y={g.mid - 4}>▼ {count} outstanding</text>
    </svg>
  );
});

function PendingZone(
  props: Omit<RowCommon, "hl" | "rel" | "proc"> & {
    model: SwimlaneModel;
    hid: string | null;
    related: ReadonlySet<string>;
    procId: string | null;
    clock?: number;
    formatWait?: (ms: number) => string;
  },
) {
  const {model, hid, related, procId, clock, formatWait, ...common} = props;
  const [tick, setNow] = useState(() => Date.now());
  const now = clock ?? tick;
  const any = model.pending.length > 0;
  useEffect(() => {
    // only the ghost rows tick (for the "waiting" timer); a `now` prop disables the ticker
    if (!any || clock != null) return;
    const iv = setInterval(() => setNow(Date.now()), 250);
    return () => clearInterval(iv);
  }, [any, clock]);
  const {current, pending} = model;
  const ghosts = useMemo(() => projectPending(current, pending), [current, pending]);
  return (
    <>
      <NowRow
        snap={model.current}
        count={model.pending.length}
        proc={procId && rowTouches({pre: model.current, post: model.current}, undefined, procId) ? procId : null}
        {...common}
      />
      {ghosts.map((gr) => (
        <GhostRow
          key={gr.id}
          row={gr}
          now={now}
          hl={hid && rowTouches(gr, gr.pending.id, hid) ? hid : null}
          rel={related.has(gr.pending.id)}
          proc={procId && rowTouches(gr, undefined, procId) ? procId : null}
          formatWait={formatWait}
          {...common}
        />
      ))}
    </>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Header
// ─────────────────────────────────────────────────────────────────────────────

function Header({model, g, headH, width}: {model: SwimlaneModel; g: Geo; headH: number; width: number}) {
  return (
    <svg width={width} height={headH}>
      {model.laneOrder.map((l, i) => {
        const x = laneX(g, i);
        const s = model.current[l];
        const y = headH - 24;
        return (
          <g key={l}>
            <text className="swl-lane-name" x={x + 4} y={y} transform={`rotate(-90 ${x + 4} ${y})`}>
              {model.laneLabels[l] ?? l}
            </text>
            <circle cx={x} cy={headH - 12} r={5} className={`swl-dot-${s?.state}`}>
              <title>{s?.state}</title>
            </circle>
            {s && s.acts.length > 0 && (
              <text className="swl-lbl-muted" x={x + 9} y={headH - 8}>
                {s.acts.length}
              </text>
            )}
            <rect
              className="swl-hit"
              x={x - g.laneW / 2}
              y={0}
              width={g.laneW}
              height={headH}
              data-kind="lane"
              data-id={l}
              data-lane={l}
            />
          </g>
        );
      })}
    </svg>
  );
}

function Defs({mk}: {mk: string}) {
  const m = (id: string, cls: string, open: boolean) => (
    <marker
      id={`${mk}-${id}`}
      viewBox="0 0 10 10"
      refX={9}
      refY={5}
      markerWidth={9}
      markerHeight={9}
      markerUnits="userSpaceOnUse"
      orient="auto-start-reverse"
    >
      {open ? <path d="M1,1 L9,5 L1,9" className={cls} /> : <path d="M0,0 L10,5 L0,10 z" className={cls} />}
    </marker>
  );
  return (
    <svg width={0} height={0} style={{position: "absolute"}} aria-hidden="true">
      <defs>
        {m("sync", "swl-mk-sync", false)}
        {m("async", "swl-mk-async", true)}
        {m("event", "swl-mk-event", true)}
        {m("reply", "swl-mk-reply", true)}
        {m("error", "swl-mk-error", false)}
        {m("ghost", "swl-mk-ghost", true)}
      </defs>
    </svg>
  );
}

/**
 * For a hovered transition (call / reply arrow, or outstanding reply): the
 * call id of the caller-side activity that sent it / receives the reply.
 */
function processOf(m: Pick<SwimlaneModel, "spans">, t: SwimlaneTarget): string | null {
  if (t.kind !== "transition" && t.kind !== "pending") return null;
  return m.spans[t.id]?.parent ?? null;
}

function scrollParent(el: HTMLElement | null): HTMLElement | null {
  for (let e = el?.parentElement; e; e = e.parentElement) {
    const oy = getComputedStyle(e).overflowY;
    if (oy === "auto" || oy === "scroll") return e;
  }
  return null; // → window
}

// ─────────────────────────────────────────────────────────────────────────────
// Card
// ─────────────────────────────────────────────────────────────────────────────

export const SwimlaneComponent = (props: PiCardProps<SwimlaneProps, SwimlaneEvents>): React.ReactNode => {
  const {
    cardName,
    model,
    showPending = true,
    autoFollow = true,
    showTooltip = true,
    highlightId,
    laneWidth = DEF_LANE_WIDTH,
    rowHeight = DEF_ROW_HEIGHT,
    headerHeight = DEF_HEADER_HEIGHT,
    gutterWidth = DEF_GUTTER_WIDTH,
    stickyTop = 0,
    now: clock,
    formatTs: fmtTs = formatTs,
    formatWait,
    className,
    style,
    onHoverChanged,
    onItemClicked,
  } = props;

  const mk = "swl" + useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const g = useMemo<Geo>(
    () => ({laneW: laneWidth, rowH: rowHeight, gutter: gutterWidth, mid: rowHeight / 2, mk}),
    [laneWidth, rowHeight, gutterWidth, mk],
  );
  const width = gutterWidth + model.laneOrder.length * laneWidth + 140; // + room for labels
  const common = {
    g,
    laneOrder: model.laneOrder,
    laneLabels: model.laneLabels,
    laneActivityClassName: model.laneActivityClassName,
    laneActivityStyle: model.laneActivityStyle,
    width,
    fmtTs,
  };

  const rootRef = useRef<HTMLDivElement>(null);
  const tipRef = useRef<HTMLDivElement>(null);
  const modelRef = useRef(model);
  modelRef.current = model;

  // ── hover / click (event delegation) ─────────────────────────────────────
  const [hovered, setHovered] = useState<SwimlaneTarget | null>(null);
  const hoveredRef = useRef<SwimlaneTarget | null>(null);

  const targetOf = (el: Element | null): SwimlaneTarget | null => {
    const hit = (el as HTMLElement | null)?.closest?.(".swl-hit") as SVGElement | null;
    if (!hit) return null;
    const d = hit.dataset;
    return {
      kind: d.kind as SwimlaneTargetKind,
      id: d.id!,
      lane: d.lane,
      // DOM dataset values are always strings; row ids may be numbers
      // (internal) or caller-chosen strings/numbers (see `SwimlaneRowId`),
      // so `rowId` is compared against `String(row.id)` rather than parsed.
      rowId: d.row,
    };
  };
  const same = (a: SwimlaneTarget | null, b: SwimlaneTarget | null) =>
    a === b || (!!a && !!b && a.kind === b.kind && a.id === b.id);

  const details = (t: SwimlaneTarget) => {
    const m = modelRef.current;
    if (t.kind === "step") return {steps: stepRows(m, t.id)};
    if (t.kind === "lane") return {meta: m.laneMeta[t.id]};
    if (t.kind === "state") {
      const r = m.rows.find((x) => String(x.id) === t.rowId);
      const meta = r && r.event.type === "state" ? r.event.meta : undefined;
      return {related: undefined, process: undefined, meta};
    }
    const related = relatedCallIds(m, t.id);
    const process = processOf(m, t) ?? undefined;
    const pending = t.kind === "pending" ? m.pending.find((p) => p.id === t.id) : undefined;
    const meta = pending ? pending.meta : m.spans[t.id]?.meta;
    return t.kind === "pending"
      ? {pending, span: m.spans[t.id], related, process, meta}
      : {span: m.spans[t.id], related, process, meta};
  };

  const placeTip = (x: number, y: number) => {
    const tip = tipRef.current;
    if (tip) {
      tip.style.left = `${x + 14}px`;
      tip.style.top = `${y + 14}px`;
    }
  };

  const changeHover = (next: SwimlaneTarget | null, e: React.PointerEvent) => {
    const prev = hoveredRef.current;
    if (same(prev, next)) return; // e.g. same activity continuing in the next row
    hoveredRef.current = next;
    setHovered(next);
    const tip = tipRef.current;
    if (tip) {
      if (next && showTooltip) {
        tip.textContent = describeSwimlaneTarget(modelRef.current, next, clock ?? Date.now(), fmtTs);
        tip.style.display = "block";
        placeTip(e.clientX, e.clientY);
      } else {
        tip.style.display = "none";
      }
    }
    onHoverChanged({
      target: next,
      previous: prev,
      ...(next ? details(next) : {}),
      clientX: e.clientX,
      clientY: e.clientY,
    });
  };

  const onOver = (e: React.PointerEvent) => {
    const t = targetOf(e.target as Element);
    if (t) changeHover(t, e);
  };
  const onOut = (e: React.PointerEvent) => {
    const t = targetOf(e.relatedTarget as Element | null);
    if (!t || !same(t, hoveredRef.current)) changeHover(t, e);
  };
  const onMove = (e: React.PointerEvent) => {
    if (hoveredRef.current && showTooltip) placeTip(e.clientX, e.clientY);
  };
  const onClick = (e: React.MouseEvent) => {
    const t = targetOf(e.target as Element);
    if (t) onItemClicked({target: t, ...details(t)});
  };

  // ── highlighting: only rows touching the chain get a new `hl` prop ───────
  const hid =
    hovered && hovered.kind !== "state" && hovered.kind !== "step" && hovered.kind !== "lane"
      ? hovered.id
      : highlightId ?? null;
  // children of the highlighted call: transitions the process creates/receives
  const {spans} = model;
  const related = useMemo<ReadonlySet<string>>(
    () => new Set(hid ? relatedCallIds({spans}, hid) : []),
    [hid, spans],
  );
  // hovering a transition: also mark the process on the caller side that sent
  // the call / receives the reply (the parent activity) — only that activity
  const procId = hovered ? processOf(model, hovered) : null;
  // hovering (or clicking) a timestamp: the whole step it belongs to
  const stepId = hovered?.kind === "step" ? hovered.id : null;

  // ── auto-follow (page or nearest scroll container) ───────────────────────
  const follow = useRef(true);
  useEffect(() => {
    if (!autoFollow) return;
    const sp = scrollParent(rootRef.current);
    const target: HTMLElement | Window = sp ?? window;
    const onScroll = () => {
      follow.current = sp
        ? sp.scrollTop + sp.clientHeight >= sp.scrollHeight - 40
        : window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 40;
    };
    target.addEventListener("scroll", onScroll, {passive: true});
    return () => target.removeEventListener("scroll", onScroll);
  }, [autoFollow]);
  useLayoutEffect(() => {
    if (!autoFollow || !follow.current) return;
    const sp = scrollParent(rootRef.current);
    if (sp) sp.scrollTop = sp.scrollHeight;
    else window.scrollTo(0, document.documentElement.scrollHeight);
  }, [autoFollow, model.rows.length, model.pending.length]);

  return (
    <div
      ref={rootRef}
      className={clsx("pihanga-swimlane", className)}
      style={style}
      data-pihanga={cardName}
      onPointerOver={onOver}
      onPointerOut={onOut}
      onPointerMove={onMove}
      onClick={onClick}
    >
      <Defs mk={mk} />
      <div className="swl-header" style={{top: stickyTop}}>
        <Header model={model} g={g} headH={headerHeight} width={width} />
      </div>
      <div className="swl-rows">
        {model.rows.map((r, i) => (
          <RealRow
            key={r.id}
            row={r}
            hl={hid && rowTouches(r, "id" in r.event ? r.event.id : undefined, hid) ? hid : null}
            rel={"id" in r.event && r.event.type !== "done" && related.has(r.event.id)}
            proc={procId && rowTouches(r, undefined, procId) ? procId : null}
            grouped={r.event.step != null && r.event.step === model.rows[i - 1]?.event.step}
            stepHl={stepId != null && stepKeyOf(r) === stepId}
            {...common}
          />
        ))}
        {showPending && (
          <PendingZone
            model={model}
            hid={hid}
            related={related}
            procId={procId}
            clock={clock}
            formatWait={formatWait}
            {...common}
          />
        )}
      </div>
      <div ref={tipRef} className="swl-tooltip" role="tooltip" />
    </div>
  );
};

/*
 * shad/swimlane — card-local colour tokens (override in your own :root / .dark).
 * Structural colours reuse the shadcn tokens (--foreground, --muted-foreground,
 * --border, --popover, --destructive) so the card follows the app theme.
 */
:root {
  --swl-sync: oklch(0.55 0.2 260);
  --swl-async: oklch(0.55 0.22 295);
  --swl-event: oklch(0.6 0.11 185);
  --swl-act-fill: oklch(0.93 0.04 255);
  --swl-hl: oklch(0.77 0.16 70);
  --swl-starting: oklch(0.67 0.16 60);
  --swl-degraded: oklch(0.65 0.19 45);
  --swl-running: oklch(0.6 0.15 150);
  /* one-shot outcome states (in_progress / succeeded / failed) — see §5 of DESIGN.md */
  --swl-in-progress: oklch(0.6 0.17 255);
  --swl-succeeded: oklch(0.6 0.15 150);
  --swl-failed: oklch(0.6 0.22 25);
}
.dark {
  --swl-sync: oklch(0.72 0.14 260);
  --swl-async: oklch(0.74 0.14 295);
  --swl-event: oklch(0.78 0.11 185);
  --swl-act-fill: oklch(0.35 0.07 255);
  --swl-hl: oklch(0.8 0.15 75);
  --swl-starting: oklch(0.75 0.15 65);
  --swl-degraded: oklch(0.72 0.17 45);
  --swl-running: oklch(0.75 0.15 150);
  --swl-in-progress: oklch(0.72 0.15 255);
  --swl-succeeded: oklch(0.75 0.15 150);
  --swl-failed: oklch(0.72 0.2 25);
}

.pihanga-swimlane {
  width: max-content;
  min-width: 100%;
  color: var(--foreground);
  font-size: 13px;
}
.pihanga-swimlane .swl-header {
  position: sticky;
  z-index: 2;
  background: var(--background);
  border-bottom: 1px solid var(--border);
}
.pihanga-swimlane svg { display: block; overflow: visible; }
.pihanga-swimlane svg text { fill: var(--foreground); }

.pihanga-swimlane .swl-lane-name { font-size: 12px; font-weight: 600; }
.pihanga-swimlane .swl-ts { fill: var(--muted-foreground); font: 10px ui-monospace, monospace; }
.pihanga-swimlane .swl-lbl { font-size: 11px; }
.pihanga-swimlane .swl-lbl-muted { font-size: 10px; fill: var(--muted-foreground); }
/* rows that share a `step` with the previous row: a tie mark instead of a
   repeated timestamp, joining them visually into one block */
.pihanga-swimlane .swl-ts-tie { stroke: var(--muted-foreground); stroke-width: 1; stroke-dasharray: 2 2; opacity: 0.5; }
/* hovering (or clicking) a timestamp highlights every row of its step */
.pihanga-swimlane .swl-row.swl-hl-step { background: color-mix(in srgb, var(--swl-hl) 12%, transparent); }
.pihanga-swimlane .swl-row.swl-hl-step .swl-ts,
.pihanga-swimlane .swl-row.swl-hl-step .swl-ts-tie { stroke: var(--swl-hl); fill: var(--swl-hl); opacity: 1; }

/* lifelines by run state */
.pihanga-swimlane .swl-ll { stroke-width: 1.5; }
.pihanga-swimlane .swl-ll-created,
.pihanga-swimlane .swl-ll-running { stroke: color-mix(in srgb, var(--muted-foreground) 70%, transparent); }
.pihanga-swimlane .swl-ll-starting { stroke: var(--swl-starting); stroke-dasharray: 4 3; }
.pihanga-swimlane .swl-ll-degraded { stroke: var(--swl-degraded); stroke-width: 3; }
.pihanga-swimlane .swl-ll-stopped { stroke: var(--border); stroke-dasharray: 1 4; }
/* one-shot outcome states: lifeline stays plain, only the dot carries colour */
.pihanga-swimlane .swl-ll-in_progress { stroke: color-mix(in srgb, var(--muted-foreground) 70%, transparent); }
.pihanga-swimlane .swl-ll-succeeded { stroke: color-mix(in srgb, var(--muted-foreground) 70%, transparent); }
.pihanga-swimlane .swl-ll-failed { stroke: color-mix(in srgb, var(--muted-foreground) 70%, transparent); }

.pihanga-swimlane .swl-dot-created,
.pihanga-swimlane .swl-dot-starting { fill: var(--swl-starting); }
.pihanga-swimlane .swl-dot-running { fill: var(--swl-running); }
.pihanga-swimlane .swl-dot-degraded { fill: var(--swl-degraded); }
.pihanga-swimlane .swl-dot-stopped { fill: var(--border); }
.pihanga-swimlane .swl-dot-in_progress { fill: var(--swl-in-progress); }
.pihanga-swimlane .swl-dot-succeeded { fill: var(--swl-succeeded); }
.pihanga-swimlane .swl-dot-failed { fill: var(--swl-failed); }
.pihanga-swimlane .swl-lane-head { fill: var(--background); stroke: var(--muted-foreground); }

/* activities */
.pihanga-swimlane .swl-act rect { fill: var(--swl-act-fill); stroke: none; }
.pihanga-swimlane .swl-act path { fill: none; stroke: var(--swl-sync); stroke-width: 1; }
.pihanga-swimlane .swl-act.swl-hl rect { fill: var(--swl-hl); }
.pihanga-swimlane .swl-act.swl-hl path { stroke: var(--swl-hl); }
/* the caller-side process that sends / receives a hovered transition */
.pihanga-swimlane .swl-act.swl-hl-proc rect { fill: color-mix(in srgb, var(--swl-hl) 45%, var(--swl-act-fill)); }
.pihanga-swimlane .swl-act.swl-hl-proc path { stroke: var(--swl-hl); stroke-width: 2; }

/* arrows */
.pihanga-swimlane .swl-ar { fill: none; stroke-width: 1.5; }
.pihanga-swimlane .swl-ar-sync { stroke: var(--swl-sync); }
.pihanga-swimlane .swl-ar-async { stroke: var(--swl-async); }
.pihanga-swimlane .swl-ar-event { stroke: var(--swl-event); stroke-dasharray: 2 3; }
.pihanga-swimlane .swl-ar-reply { stroke: var(--muted-foreground); stroke-dasharray: 5 3; }
.pihanga-swimlane .swl-ar-error { stroke: var(--destructive); stroke-dasharray: 5 3; }
.pihanga-swimlane .swl-ar-ghost { stroke: var(--muted-foreground); stroke-dasharray: 7 4; }
.pihanga-swimlane .swl-ar-ghost.swl-overdue { stroke: var(--destructive); }
.pihanga-swimlane .swl-ar.swl-hl { stroke: var(--swl-hl); stroke-width: 3; }
/* transitions created / received by the highlighted process */
.pihanga-swimlane .swl-ar.swl-hl-rel { stroke: var(--swl-hl); stroke-width: 2; }

.pihanga-swimlane .swl-mk-sync { fill: var(--swl-sync); }
.pihanga-swimlane .swl-mk-async { fill: none; stroke: var(--swl-async); stroke-width: 1.5; }
.pihanga-swimlane .swl-mk-event { fill: none; stroke: var(--swl-event); stroke-width: 1.5; }
.pihanga-swimlane .swl-mk-reply,
.pihanga-swimlane .swl-mk-ghost { fill: none; stroke: var(--muted-foreground); stroke-width: 1.5; }
.pihanga-swimlane .swl-mk-error { fill: var(--destructive); }

/* outstanding zone */
.pihanga-swimlane .swl-ghost { opacity: 0.55; }
.pihanga-swimlane .swl-ts.swl-overdue { fill: var(--destructive); font-weight: 600; }
.pihanga-swimlane .swl-now-line { stroke: var(--swl-hl); stroke-width: 1.5; stroke-dasharray: 10 4; }
.pihanga-swimlane text.swl-now-lbl { fill: var(--swl-hl); font-size: 11px; font-weight: 600; }
.pihanga-swimlane text.swl-ok { fill: var(--swl-running); font-size: 12px; font-weight: 700; }
/* an outstanding reply that arrived as an error still "arrived", but isn't a success */
.pihanga-swimlane text.swl-ok.swl-ok-error { fill: var(--destructive); }
.pihanga-swimlane .swl-arrived { animation: swl-arrive 1.6s ease-out; }
@keyframes swl-arrive {
  0% { background: color-mix(in srgb, var(--swl-hl) 45%, transparent); }
  100% { background: transparent; }
}

/* hit zones: invisible but receive the pointer */
.pihanga-swimlane .swl-hit { fill: transparent; stroke: transparent; cursor: pointer; }
/* lane header: subtle hover affordance on the name/dot click target */
.pihanga-swimlane .swl-hit[data-kind="lane"]:hover { fill: color-mix(in srgb, var(--swl-hl) 10%, transparent); }
.pihanga-swimlane.swl-debug-hits .swl-hit {
  fill: color-mix(in srgb, var(--destructive) 10%, transparent);
  stroke: color-mix(in srgb, var(--destructive) 20%, transparent);
}

.pihanga-swimlane .swl-tooltip {
  position: fixed;
  z-index: 50;
  display: none;
  max-width: 340px;
  pointer-events: none;
  padding: 6px 8px;
  border-radius: calc(var(--radius) - 2px);
  border: 1px solid var(--border);
  background: var(--popover);
  color: var(--popover-foreground);
  font-size: 12px;
  box-shadow: 0 4px 12px color-mix(in srgb, var(--foreground) 15%, transparent);
}

/**
 * Deterministic demo event scripts for the playground and tests.
 * (No randomness: every run produces the same diagram.)
 */
import {createSwimlaneModel, ingestSwimlaneEvents} from "./swimlane.model";
import type {SwimlaneEvent, SwimlaneModel} from "./swimlane.types";

/**
 * A checkout flow through a small microservice deployment, stopped while
 * several replies and one announced callback are still outstanding.
 */
export function demoEvents(t0: number, opts: {complete?: boolean} = {}): SwimlaneEvent[] {
  let t = t0;
  const at = <E extends SwimlaneEvent>(e: E, dt = 350): E => ({...e, ts: (t += dt)});
  const ev: SwimlaneEvent[] = [
    at({type: "lane", lane: "client"}),
    at({type: "lane", lane: "gateway", label: "api-gateway"}),
    at({type: "state", lane: "gateway", state: "running"}),
    at({type: "call", kind: "sync", id: "c1", from: "client", to: "gateway", label: "POST /checkout"}),
    at({type: "call", kind: "sync", id: "c2", from: "gateway", to: "auth", label: "verify token", timeoutMs: 1500}),
    at({type: "state", lane: "auth", state: "running"}),
    at({type: "reply", id: "c2", ok: true, label: "200 OK"}),
    at({type: "call", kind: "sync", id: "c3", from: "gateway", to: "orders", label: "createOrder"}),
    at({type: "state", lane: "orders", state: "running"}),
    at({type: "call", kind: "sync", id: "c4", from: "orders", to: "orders", label: "validate"}),
    at({type: "reply", id: "c4", ok: true, label: "ok"}),
    at({type: "call", kind: "sync", id: "c5", from: "orders", to: "inventory", label: "reserve items"}),
    at({type: "state", lane: "inventory", state: "degraded"}),
    at({type: "reply", id: "c5", ok: true, label: "200 OK"}),
    at({type: "state", lane: "inventory", state: "running"}),
    at({type: "call", kind: "sync", id: "c6", from: "orders", to: "payments", label: "charge card", timeoutMs: 1200}),
    at({type: "reply", id: "c6", ok: false, label: "402 declined"}),
    at({type: "call", kind: "sync", id: "c7", from: "orders", to: "payments", label: "charge card (retry)", timeoutMs: 1200}),
    at({type: "reply", id: "c7", ok: true, label: "200 OK"}),
    at({type: "call", kind: "async", id: "c8", from: "orders", to: "notifier", label: "order.created"}),
    // we KNOW notifier will call back later
    at({type: "expect", id: "x1", from: "notifier", to: "orders", label: "email.sent", timeoutMs: 8000}, 0),
    at({type: "call", kind: "event", id: "c9", from: "orders", to: "audit", label: "audit.log"}),
    at({type: "state", lane: "audit", state: "stopped"}),
    at({type: "call", kind: "sync", id: "c10", from: "notifier", to: "notifier", label: "render email"}),
  ];
  if (opts.complete) {
    ev.push(
      at({type: "reply", id: "c10", ok: true, label: "ok"}),
      at({type: "call", kind: "event", id: "c11", from: "notifier", to: "orders", label: "email.sent", fulfils: "x1"}),
      at({type: "done", id: "c8"}),
      at({type: "reply", id: "c3", ok: true, label: "200 OK"}),
      at({type: "reply", id: "c1", ok: true, label: "201 Created"}),
      at({type: "state", lane: "audit", state: "starting"}),
      at({type: "state", lane: "audit", state: "running"}),
    );
  }
  return ev;
}

export function buildDemoModel(opts: {complete?: boolean; t0?: number} = {}): SwimlaneModel {
  const events = demoEvents(opts.t0 ?? Date.now() - 12_000, opts);
  const m = createSwimlaneModel();
  ingestSwimlaneEvents(m, events);
  return m;
}

/**
 * Swimlane model helpers — pure TypeScript, no React.
 *
 * The model is plain JSON that lives in the app's Redux state.
 * `ingestSwimlaneEvents` MUTATES the model it is given, which is exactly what
 * a Pihanga (Immer) reducer wants:
 *
 *   onSwimlaneEventsReceived<AppState>(r, (state, {events}) => {
 *     ingestSwimlaneEvents(state.swimlane, events);
 *   });
 *
 * or simply `registerSwimlaneModel(r, "main", (s) => s.swimlane)`.
 *
 * Every row stores its own plain copies of the lane snapshots, so no object is
 * ever referenced from two places in the state tree (Immer-safe, serialisable).
 */
import type {PiRegister, ReduxState} from "@pihanga2/core";
import type React from "react";

import {
  DEF_MAX_ROWS,
  onSwimlaneEventsReceived,
  onSwimlaneRowsCleared,
  type SwimlaneEvent,
  type SwimlaneGhostRow,
  type SwimlaneLanesSnapshot,
  type SwimlaneModel,
  type SwimlanePending,
  type SwimlaneRow,
  type SwimlaneRowEvent,
  type SwimlaneRowId,
  type SwimlaneRunState,
  type SwimlaneTarget,
} from "./swimlane.types";

export type SwimlaneSeedLane = {
  lane: string;
  label?: string;
  /** Initial run state. Default `"created"`, same as an ordinary `lane` event. */
  state?: SwimlaneRunState;
  meta?: unknown;
  /** See `SwimlaneLaneEvent.activityClassName`. */
  activityClassName?: string;
  /** See `SwimlaneLaneEvent.activityStyle`. */
  activityStyle?: React.CSSProperties;
};

export function createSwimlaneModel(
  opts: {maxRows?: number; lanes?: SwimlaneSeedLane[]} = {},
): SwimlaneModel {
  const laneOrder: string[] = [];
  const laneLabels: Record<string, string> = {};
  const laneMeta: Record<string, unknown> = {};
  const laneActivityClassName: Record<string, string> = {};
  const laneActivityStyle: Record<string, React.CSSProperties> = {};
  const current: SwimlaneLanesSnapshot = {};
  for (const l of opts.lanes ?? []) {
    if (current[l.lane]) continue; // ignore duplicates, first wins
    laneOrder.push(l.lane);
    current[l.lane] = {state: l.state ?? "created", acts: []};
    if (l.label) laneLabels[l.lane] = l.label;
    if ("meta" in l) laneMeta[l.lane] = l.meta;
    if (l.activityClassName) laneActivityClassName[l.lane] = l.activityClassName;
    if (l.activityStyle) laneActivityStyle[l.lane] = l.activityStyle;
  }
  return {
    laneOrder,
    laneLabels,
    laneMeta,
    laneActivityClassName,
    laneActivityStyle,
    current,
    rows: [],
    pending: [],
    spans: {},
    seq: 0,
    maxRows: opts.maxRows ?? DEF_MAX_ROWS,
  };
}

function copySnapshot(s: SwimlaneLanesSnapshot): SwimlaneLanesSnapshot {
  const out: SwimlaneLanesSnapshot = {};
  for (const k of Object.keys(s)) {
    out[k] = {state: s[k].state, acts: [...s[k].acts]};
  }
  return out;
}

/**
 * The id to assign a new row for `ev`: its own `rowId` when set and not
 * already in use by an existing row, the model's internal counter
 * otherwise. See `SwimlaneEventBase.rowId`.
 */
function rowId(m: SwimlaneModel, ev: SwimlaneEvent): SwimlaneRowId {
  if (ev.rowId != null && !m.rows.some((r) => r.id === ev.rowId)) return ev.rowId;
  return ++m.seq;
}

/** Lanes an event refers to (used to add lanes implicitly). */
function referencedLanes(m: SwimlaneModel, ev: SwimlaneEvent): string[] {
  switch (ev.type) {
    case "state":
      return [ev.lane];
    case "call":
      return ev.from === ev.to ? [ev.from] : [ev.from, ev.to];
    case "expect":
      return ev.from === ev.to ? [ev.from] : [ev.from, ev.to];
    case "reply":
    case "done": {
      const s = m.spans[ev.id];
      return s ? [s.to, s.from] : [];
    }
    default:
      return [];
  }
}

/**
 * Apply a batch of stream events to the model (mutating it).
 * Safe to call on an Immer draft or on a plain object.
 */
export function ingestSwimlaneEvents(
  m: SwimlaneModel,
  events: SwimlaneEvent[],
  now: number = Date.now(),
): void {
  for (const raw of events) {
    const ts = raw.ts ?? now;
    // lanes referenced before they were announced get an implicit lane row
    for (const lane of referencedLanes(m, raw)) {
      if (!m.current[lane]) applyOne(m, {type: "lane", lane}, ts);
    }
    applyOne(m, raw, ts);
  }
  trim(m);
}

function applyOne(m: SwimlaneModel, ev: SwimlaneEvent, ts: number): void {
  const cur = m.current;

  if (ev.type === "expect") {
    m.pending.push({
      id: ev.id,
      type: "expect",
      from: ev.from,
      to: ev.to,
      label: ev.label,
      since: ts,
      timeoutMs: ev.timeoutMs,
      meta: ev.meta,
    });
    return;
  }

  const pre = copySnapshot(cur);
  let route: SwimlaneRow["route"];

  switch (ev.type) {
    case "lane": {
      if (ev.label) m.laneLabels[ev.lane] = ev.label;
      if ("meta" in ev) m.laneMeta[ev.lane] = ev.meta;
      if (ev.activityClassName) m.laneActivityClassName[ev.lane] = ev.activityClassName;
      if (ev.activityStyle) m.laneActivityStyle[ev.lane] = ev.activityStyle;
      const isNew = !cur[ev.lane];
      if (isNew) {
        cur[ev.lane] = {state: "created", acts: []};
        m.laneOrder.push(ev.lane);
      }
      // no row for: an already-known lane (label/meta/style-only update), or
      // a brand-new lane whose announcement opted out via `announce: false`
      if (!isNew || ev.announce === false) return;
      break;
    }
    case "state":
      cur[ev.lane].state = ev.state;
      break;
    case "call": {
      // causality: explicit parentId, else the innermost open activity of the caller
      const callerActs = cur[ev.from]?.acts ?? [];
      const parent = ev.parentId ?? callerActs[callerActs.length - 1];
      m.spans[ev.id] = {
        id: ev.id,
        kind: ev.kind,
        from: ev.from,
        to: ev.to,
        label: ev.label,
        start: ts,
        end: ev.kind === "event" ? ts : undefined,
        status: ev.kind === "event" ? "done" : "open",
        meta: ev.meta,
      };
      if (parent && parent !== ev.id) m.spans[ev.id].parent = parent;
      if (ev.kind !== "event") cur[ev.to].acts.push(ev.id);
      break;
    }
    case "reply":
    case "done": {
      const s = m.spans[ev.id];
      if (!s) return; // unknown call → nothing sensible to draw
      s.end = ts;
      s.status = ev.type === "done" ? "done" : ev.ok ? "ok" : "error";
      if (ev.type === "reply") s.result = ev.label;
      const lane = cur[s.to];
      if (lane) {
        const i = lane.acts.indexOf(ev.id);
        if (i >= 0) lane.acts.splice(i, 1);
      }
      route = {from: s.from, to: s.to, label: s.label};
      break;
    }
  }

  // does this real event replace an outstanding one?
  let fulfilled: string | undefined;
  const pid = ev.type === "reply" ? ev.id : ev.fulfils;
  if (pid) {
    const i = m.pending.findIndex((p) => p.id === pid);
    if (i >= 0) {
      m.pending.splice(i, 1);
      fulfilled = pid;
    }
  }
  // a sync call means we KNOW a reply will come back
  if (ev.type === "call" && ev.kind === "sync") {
    m.pending.push({
      id: ev.id,
      type: "reply",
      from: ev.to,
      to: ev.from,
      label: `reply: ${ev.label}`,
      since: ts,
      timeoutMs: ev.timeoutMs,
      meta: ev.meta,
    });
  }

  const row: SwimlaneRow = {
    id: rowId(m, ev),
    event: {...ev, ts} as SwimlaneRowEvent,
    pre,
    post: copySnapshot(cur),
  };
  if (fulfilled) row.fulfilled = fulfilled;
  if (route) row.route = route;
  m.rows.push(row);
}

/** Ring buffer with amortised span garbage collection. */
function trim(m: SwimlaneModel): void {
  const slack = Math.max(50, Math.floor(m.maxRows / 10));
  if (m.rows.length <= m.maxRows + slack) return;
  m.rows.splice(0, m.rows.length - m.maxRows);
  const keep = new Set<string>();
  for (const r of m.rows) {
    if ("id" in r.event) keep.add(r.event.id);
  }
  for (const l of Object.values(m.current)) l.acts.forEach((a) => keep.add(a));
  m.pending.forEach((p) => keep.add(p.id));
  for (const id of Object.keys(m.spans)) {
    if (!keep.has(id)) delete m.spans[id];
  }
}

/** Remove all rows but keep lanes, open activities and outstanding messages. */
export function clearSwimlaneRows(m: SwimlaneModel): void {
  m.rows.splice(0, m.rows.length);
}

/**
 * Project outstanding messages below the "now" line (pure).
 * Expected replies are replayed onto the current snapshot so that open
 * activities visibly run down to the ghost reply that will close them.
 * Newest first ≈ innermost call replies first.
 */
export function projectPending(
  current: SwimlaneLanesSnapshot,
  pending: SwimlanePending[],
): SwimlaneGhostRow[] {
  let snap = current;
  const out: SwimlaneGhostRow[] = [];
  for (let i = pending.length - 1; i >= 0; i--) {
    const p = pending[i];
    const pre = snap;
    const lane = snap[p.from];
    if (p.type === "reply" && lane?.acts.includes(p.id)) {
      snap = {...snap, [p.from]: {...lane, acts: lane.acts.filter((a) => a !== p.id)}};
    }
    out.push({id: `g-${p.id}`, pending: p, pre, post: snap});
  }
  return out;
}

/**
 * Direct children of call `id`: calls made while it was being handled.
 * Their call/reply transitions (and outstanding replies) are the transitions
 * the process "creates and receives".
 */
export function relatedCallIds(m: Pick<SwimlaneModel, "spans">, id: string): string[] {
  const out: string[] = [];
  for (const s of Object.values(m.spans)) if (s.parent === id) out.push(s.id);
  return out.sort((a, b) => m.spans[a].start - m.spans[b].start);
}

/** Does a row (or ghost row) involve the call chain `id`? */
export function rowTouches(
  r: {pre: SwimlaneLanesSnapshot; post: SwimlaneLanesSnapshot},
  eventId: string | undefined,
  id: string,
): boolean {
  if (eventId === id) return true;
  for (const l of Object.values(r.pre)) if (l.acts.includes(id)) return true;
  for (const l of Object.values(r.post)) if (l.acts.includes(id)) return true;
  return false;
}

/**
 * Identifies the "step" a row belongs to: rows that share an explicit
 * `step` value, or the row itself when it has none (a step of one event).
 */
export function stepKeyOf(r: Pick<SwimlaneRow, "id" | "event">): string {
  return r.event.step != null ? `step:${r.event.step}` : `row:${r.id}`;
}

/** Every row belonging to the same step as `t` (see `stepKeyOf`), in `model.rows` order. */
export function stepRows(m: SwimlaneModel, stepId: string): SwimlaneRow[] {
  return m.rows.filter((r) => stepKeyOf(r) === stepId);
}

export function formatTs(t: number): string {
  const d = new Date(t);
  const p = (n: number, w = 2) => String(n).padStart(w, "0");
  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}.${p(d.getMilliseconds(), 3)}`;
}

/** Human-readable description of a hover target (used by the tooltip). */
export function describeSwimlaneTarget(
  m: SwimlaneModel,
  t: SwimlaneTarget,
  now: number = Date.now(),
  fmtTs: (ts: number) => string = formatTs,
): string {
  if (t.kind === "state") {
    // `rowId` may come from a DOM dataset (always a string) or be set
    // programmatically as a number, so compare stringified.
    const r = m.rows.find((x) => String(x.id) === String(t.rowId));
    if (!r || r.event.type !== "state") return t.id;
    return `${t.lane} → ${r.event.state} at ${fmtTs(r.event.ts)}`;
  }
  if (t.kind === "step") {
    const rows = stepRows(m, t.id);
    if (rows.length === 0) return t.id;
    const kinds = rows.map((r) => r.event.type).join(", ");
    return `step at ${fmtTs(rows[0].event.ts)} · ${rows.length} event${rows.length === 1 ? "" : "s"} (${kinds})`;
  }
  if (t.kind === "lane") {
    const s = m.current[t.id];
    return `${m.laneLabels[t.id] ?? t.id}${s ? ` · ${s.state}` : ""}`;
  }
  if (t.kind === "pending") {
    const p = m.pending.find((x) => x.id === t.id);
    if (!p) return "already fulfilled";
    const w = now - p.since;
    const what = p.type === "reply" ? "reply" : "message";
    const to = p.timeoutMs
      ? ` / timeout ${p.timeoutMs} ms${w > p.timeoutMs ? " · OVERDUE" : ""}`
      : "";
    return `expected ${what} ${p.from} → ${p.to}: "${p.label}" · waiting ${w} ms${to}`;
  }
  const s = m.spans[t.id];
  if (!s) return t.id;
  const dur = s.end != null ? `${s.end - s.start} ms` : `running ${now - s.start} ms`;
  const res = s.result ? ` (${s.result})` : "";
  if (t.kind === "activity") {
    return `${s.to} handling "${s.label}" from ${s.from} · started ${fmtTs(s.start)} · ${dur}${res}`;
  }
  return `${s.kind.toUpperCase()} ${s.from} → ${s.to}: "${s.label}" · ${s.status}${res} · ${dur}`;
}

/**
 * Wire the data actions for one model:
 *
 *   register((r) => registerSwimlaneModel<AppState>(r, "main", (s) => s.swimlane));
 *   // …later, from a stream adapter:
 *   dispatchSwimlaneEvents(dispatch, {modelId: "main", events});
 */
export function registerSwimlaneModel<S extends ReduxState>(
  r: PiRegister,
  modelId: string,
  select: (state: S) => SwimlaneModel,
): void {
  onSwimlaneEventsReceived<S>(r, (state, a) => {
    if (a.modelId === modelId) ingestSwimlaneEvents(select(state), a.events);
  });
  onSwimlaneRowsCleared<S>(r, (state, a) => {
    if (a.modelId === modelId) clearSwimlaneRows(select(state));
  });
}

import {
  createCardDeclaration,
  createOnAction,
  createOnDispatch,
  registerActions,
} from "@pihanga2/core";
import type React from "react";

// ─────────────────────────────────────────────────────────────────────────────
// Card identity
// ─────────────────────────────────────────────────────────────────────────────

export const SWIMLANE_CARD = "shad/swimlane";

export const Swimlane = createCardDeclaration<SwimlaneProps, SwimlaneEvents>(
  SWIMLANE_CARD,
);

// ─────────────────────────────────────────────────────────────────────────────
// Actions EMITTED by the card (user interaction)
// ─────────────────────────────────────────────────────────────────────────────

export const SWIMLANE_ACTION = registerActions(SWIMLANE_CARD, [
  "hover_changed",
  "item_clicked",
]);

export const onSwimlaneHoverChanged = createOnAction<SwimlaneHoverChangedEvent>(
  SWIMLANE_ACTION.HOVER_CHANGED,
);

export const onSwimlaneItemClicked = createOnAction<SwimlaneItemClickedEvent>(
  SWIMLANE_ACTION.ITEM_CLICKED,
);

// ─────────────────────────────────────────────────────────────────────────────
// Actions CONSUMED by the app (feeding the model).
//
// These are not emitted by the card. They are a convenience so that stream
// adapters (WebSocket, SSE, polling …) can push events with a typed dispatcher
// and apps can wire the model with a single `registerSwimlaneModel()` call
// (see swimlane.model.ts).
// ─────────────────────────────────────────────────────────────────────────────

export const SWIMLANE_DATA_ACTION = registerActions(`${SWIMLANE_CARD}/data`, [
  "events_received",
  "rows_cleared",
]);

export const dispatchSwimlaneEvents =
  createOnDispatch<SwimlaneEventsReceivedEvent>(
    SWIMLANE_DATA_ACTION.EVENTS_RECEIVED,
  );
export const dispatchSwimlaneRowsCleared =
  createOnDispatch<SwimlaneRowsClearedEvent>(SWIMLANE_DATA_ACTION.ROWS_CLEARED);

export const onSwimlaneEventsReceived =
  createOnAction<SwimlaneEventsReceivedEvent>(
    SWIMLANE_DATA_ACTION.EVENTS_RECEIVED,
  );
export const onSwimlaneRowsCleared = createOnAction<SwimlaneRowsClearedEvent>(
  SWIMLANE_DATA_ACTION.ROWS_CLEARED,
);

// ─────────────────────────────────────────────────────────────────────────────
// Incoming stream events (what a monitored deployment reports)
// All timestamps are epoch milliseconds; `ts` is filled in on ingest if absent.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Run state of a service, drawn on its lifeline.
 *
 * `created` … `stopped` describe a long-running service's lifecycle.
 * `in_progress` / `succeeded` / `failed` are first-class outcome states for
 * one-shot work (e.g. a tool call or task) that does not fit that lifecycle —
 * use these instead of borrowing `running` / `stopped` / `degraded`.
 */
export type SwimlaneRunState =
  | "created"
  | "starting"
  | "running"
  | "degraded"
  | "stopped"
  | "in_progress"
  | "succeeded"
  | "failed";

/**
 * How a message travels between lanes.
 * - `sync`  – request that expects a reply; opens an activity on the target
 *             and automatically creates an *outstanding reply*.
 * - `async` – message that opens an activity on the target, closed by `done`.
 * - `event` – fire-and-forget; no activity.
 */
export type SwimlaneCallKind = "sync" | "async" | "event";

/** Row id: either an internal counter value, or a caller-supplied value (see `rowId`). */
export type SwimlaneRowId = string | number;

type SwimlaneEventBase = {
  /** Epoch ms. Defaults to `Date.now()` at ingest time. */
  ts?: number;
  /** Id of an `expect` event that this real event resolves. */
  fulfils?: string;
  /**
   * Use this as the resulting row's id instead of the model's internal
   * counter. Lets a caller that rebuilds the whole model from scratch on
   * every refresh (e.g. to replay a run, or after a rollback to an earlier
   * point) keep row ids stable across rebuilds, instead of them being
   * renumbered each time.
   *
   * Contract: must be unique among the model's current rows (an id freed by
   * ring-buffer trimming may be reused). If it collides with an existing
   * row, the card falls back to an internal id for that row rather than
   * producing two rows with the same id — check `SwimlaneRow.id` if you
   * need to confirm which id was actually used.
   *
   * Distinct from a `call`/`reply`/`done` event's own `id` (the call id,
   * shared between its call and reply rows) — `rowId` identifies one row.
   */
  rowId?: SwimlaneRowId;
  /**
   * Groups events that belong to one logical step (for example several
   * calls and a state change produced by a single engine tick). Rows are
   * grouped only when adjacent in `rows` (ingest order): the card draws the
   * timestamp for the first row of a run of same-`step` rows and replaces
   * it with a connecting mark on the rest, joining them into one block.
   * Comparison is `===`; omit it to draw every row on its own line as before.
   */
  step?: string | number;
  /**
   * Arbitrary caller data, opaque to the card. Carried onto the row (and,
   * for `call`/`expect` events, the resulting span/pending message) and
   * echoed back verbatim in `onHoverChanged` / `onItemClicked` for that
   * target — so the caller does not need a side table to recover context
   * (e.g. which domain object a row/span id stands for) on every hover or
   * click. Not interpreted or serialised specially by the card.
   */
  meta?: unknown;
};

/** A service became known. Lanes referenced by calls are also added implicitly. */
export type SwimlaneLaneEvent = SwimlaneEventBase & {
  type: "lane";
  lane: string;
  /** Display name (defaults to `lane`). */
  label?: string;
  /**
   * Extra class(es) added to this lane's activity bar (the `<g className="swl-act">`
   * drawn on the lifeline while the lane is handling a call), alongside the
   * default `swl-act`/highlight classes. Use this to give different lane
   * *types* their own themed colour via CSS (e.g. `.swl-act-tool rect {
   * fill: var(--my-tool-color); }`) instead of hard-coding colours per lane.
   * Most recent `lane` event for a lane wins, same as `label`/`meta`.
   */
  activityClassName?: string;
  /**
   * Inline style merged onto the activity bar's `<rect>` (fill) and `<path>`
   * (border) elements, for one-off colours that don't warrant a CSS class.
   * Takes precedence over `activityClassName`'s rules for any property it
   * sets. Most recent `lane` event for a lane wins, same as `label`/`meta`.
   */
  activityStyle?: React.CSSProperties;
  /**
   * When `false`, this event still registers the lane (and updates its
   * label/meta/activity style exactly as usual) but produces no row — as if
   * the lane had been present from the start via `createSwimlaneModel({lanes})`.
   * Only has an effect the first time a lane is seen: a later `lane` event
   * for an already-known lane never produces a row regardless of
   * `announce` (same as today), so there is no way to retroactively force a
   * "joined" row to appear for a lane once it is known. Default `true`.
   */
  announce?: boolean;
};

/** A service changed its run state. */
export type SwimlaneStateEvent = SwimlaneEventBase & {
  type: "state";
  lane: string;
  state: SwimlaneRunState;
  /** Draw the "→ state" text beside the dot. Default `true`. */
  showLabel?: boolean;
};

/** A message between two lanes (or a lane and itself). */
export type SwimlaneCallEvent = SwimlaneEventBase & {
  type: "call";
  /** Unique id; replies / `done` refer to it. */
  id: string;
  kind: SwimlaneCallKind;
  from: string;
  to: string;
  label: string;
  /** For `sync`: when the expected reply becomes overdue (ms after `ts`). */
  timeoutMs?: number;
  /**
   * Id of the call whose processing caused this call (like a trace's parent
   * span id). When omitted it is inferred at ingest time as the innermost
   * activity open on the `from` lane — exact for sequential processing, a
   * best guess when one service handles several requests concurrently.
   */
  parentId?: string;
};

/** Reply to an earlier `sync` call (drawn from callee back to caller). */
export type SwimlaneReplyEvent = SwimlaneEventBase & {
  type: "reply";
  /** Id of the originating call. */
  id: string;
  ok: boolean;
  label: string;
};

/** Processing of an earlier `async` call finished (closes the activity). */
export type SwimlaneDoneEvent = SwimlaneEventBase & {
  type: "done";
  id: string;
};

/**
 * Announces a message that is KNOWN to arrive later (from → to).
 * Shown as an outstanding ghost row until a real event with `fulfils: id`
 * arrives. Does not create a row itself.
 */
export type SwimlaneExpectEvent = SwimlaneEventBase & {
  type: "expect";
  id: string;
  from: string;
  to: string;
  label: string;
  timeoutMs?: number;
};

export type SwimlaneEvent =
  | SwimlaneLaneEvent
  | SwimlaneStateEvent
  | SwimlaneCallEvent
  | SwimlaneReplyEvent
  | SwimlaneDoneEvent
  | SwimlaneExpectEvent;

// ─────────────────────────────────────────────────────────────────────────────
// Model (lives in the app's Redux state; plain JSON)
// ─────────────────────────────────────────────────────────────────────────────

export type SwimlaneLaneSnapshot = {
  state: SwimlaneRunState;
  /** Ids of calls currently being handled by this lane (stack order). */
  acts: string[];
};

/** Lane id → snapshot. A lane missing from the record does not exist (yet). */
export type SwimlaneLanesSnapshot = Record<string, SwimlaneLaneSnapshot>;

/** A row event is any stream event except `expect` (which never makes a row). */
export type SwimlaneRowEvent = Exclude<SwimlaneEvent, SwimlaneExpectEvent> & {
  ts: number;
};

/**
 * One rendered transition. `pre` / `post` are the lane snapshots before and
 * after the event: the top half of the row is drawn from `pre`, the bottom
 * half from `post`.
 */
export type SwimlaneRow = {
  /**
   * The event's own `rowId` when it was set and did not collide with an
   * existing row; an internally assigned number otherwise. See
   * `SwimlaneEventBase.rowId`.
   */
  id: SwimlaneRowId;
  event: SwimlaneRowEvent;
  pre: SwimlaneLanesSnapshot;
  post: SwimlaneLanesSnapshot;
  /** Set when this event replaced an outstanding (expected) message. */
  fulfilled?: string;
  /**
   * For `reply` / `done` rows: the originating call, resolved at ingest time
   * so the row stays drawable after its span has been garbage-collected.
   */
  route?: {from: string; to: string; label: string};
};

/** An outstanding message projected below the "now" line. */
export type SwimlaneGhostRow = {
  id: string;
  pending: SwimlanePending;
  pre: SwimlaneLanesSnapshot;
  post: SwimlaneLanesSnapshot;
};

/** A message that is known to be coming. */
export type SwimlanePending = {
  id: string;
  /** `reply` = implied by a sync call; `expect` = announced explicitly. */
  type: "reply" | "expect";
  from: string;
  to: string;
  label: string;
  since: number;
  timeoutMs?: number;
  /** Copied from the originating `call` (implied reply) or `expect` event. */
  meta?: unknown;
};

/** Lifecycle of a call, used for tooltips and hover payloads. */
export type SwimlaneSpan = {
  id: string;
  kind: SwimlaneCallKind;
  from: string;
  to: string;
  label: string;
  start: number;
  end?: number;
  status: "open" | "ok" | "error" | "done";
  result?: string;
  /** Call whose processing caused this one (explicit `parentId` or inferred). */
  parent?: string;
  /** Copied from the originating `call` event. */
  meta?: unknown;
};

export type SwimlaneModel = {
  /** Lane ids in display (arrival) order. */
  laneOrder: string[];
  /** Optional display names. */
  laneLabels: Record<string, string>;
  /** Caller `meta` from each lane's `lane` event(s), most recent wins. */
  laneMeta: Record<string, unknown>;
  /** `activityClassName` from each lane's `lane` event(s)/seed, most recent wins. */
  laneActivityClassName: Record<string, string>;
  /** `activityStyle` from each lane's `lane` event(s)/seed, most recent wins. */
  laneActivityStyle: Record<string, React.CSSProperties>;
  /** Current snapshot (== `post` of the last row). */
  current: SwimlaneLanesSnapshot;
  rows: SwimlaneRow[];
  pending: SwimlanePending[];
  spans: Record<string, SwimlaneSpan>;
  /** Last assigned row id. */
  seq: number;
  /** Ring-buffer size for `rows`. */
  maxRows: number;
};

// ─────────────────────────────────────────────────────────────────────────────
// Card props & events
// ─────────────────────────────────────────────────────────────────────────────

export type SwimlaneProps = {
  /** The model to render — usually a state selector `(s) => s.swimlane`. */
  model: SwimlaneModel;

  /** Show outstanding messages below the "now" line. Default `true`. */
  showPending?: boolean;

  /**
   * Keep the newest row in view while the user is at the bottom of the
   * scroll container. Scrolling up pauses following. Default `true`.
   */
  autoFollow?: boolean;

  /** Show the built-in hover tooltip. Default `true`. */
  showTooltip?: boolean;

  /**
   * Highlight a call chain (call, activity, reply, outstanding reply) by id,
   * in addition to whatever the pointer is hovering.
   */
  highlightId?: string;

  /** Horizontal distance between lifelines in px. Default 104. */
  laneWidth?: number;
  /** Height of each transition row in px. Default 30. */
  rowHeight?: number;
  /** Height of the header holding the vertical lane names. Default 130. */
  headerHeight?: number;
  /** Width of the left timestamp column in px. Default 92. */
  gutterWidth?: number;
  /** `top` offset for the sticky header (e.g. height of a navbar). Default 0. */
  stickyTop?: number;

  /**
   * Clock (epoch ms) used for "waiting …" timers and overdue detection of
   * outstanding messages. When omitted the card ticks its own wall clock
   * (4×/s, only while something is outstanding). Pass it to drive the card
   * entirely from props — e.g. for replaying a recorded trace or for tests.
   */
  now?: number;

  /**
   * Formats the timestamp column (`ts`, epoch ms). Defaults to `formatTs`
   * from `swimlane.model` (local wall-clock `HH:MM:SS.mmm`). Override to
   * show a different clock — e.g. a virtual time derived from `ts`, or both
   * virtual and wall-clock time in one string.
   */
  formatTs?: (ts: number) => string;

  /**
   * Formats the "waiting …" duration (ms) shown on outstanding messages
   * below the "now" line. Defaults to `${(ms / 1000).toFixed(1)}s`.
   */
  formatWait?: (ms: number) => string;

  className?: string;
  /** Inline styles for the card's root element, alongside `className`. */
  style?: React.CSSProperties;
};

/** What the pointer is over. */
export type SwimlaneTargetKind = "transition" | "activity" | "state" | "pending" | "step" | "lane";

export type SwimlaneTarget = {
  kind: SwimlaneTargetKind;
  /**
   * Call id (`transition`/`activity`/`pending`), `state-<rowId>` (`state`),
   * the row's `step` value stringified (`step`), or the lane id (`lane`).
   */
  id: string;
  lane?: string;
  rowId?: SwimlaneRowId;
};

export type SwimlaneHoverChangedEvent = {
  /** New hover target, or `null` when the pointer left all targets. */
  target: SwimlaneTarget | null;
  /** Target that was hovered before, if any. */
  previous: SwimlaneTarget | null;
  /** Span details for the new target (when it refers to a call). */
  span?: SwimlaneSpan;
  /** Outstanding message details when `target.kind === "pending"`. */
  pending?: SwimlanePending;
  /**
   * Calls made while handling the hovered call (its direct children). Their
   * call and reply transitions are highlighted as well.
   */
  related?: string[];
  /**
   * For a hovered transition: call id of the caller-side process (activity)
   * that sent the call and receives its reply. That activity is highlighted.
   */
  process?: string;
  /** For `target.kind === "step"`: every row belonging to that step. */
  steps?: SwimlaneRow[];
  /**
   * Caller `meta` for the target, if any was set on the originating event:
   * the `call`'s `meta` for `transition`/`activity`/`pending`, the `state`
   * event's `meta` for `state`, the `lane` event's `meta` for `lane`. Not
   * set for `step` (see `steps`, which carries each row's own event/meta).
   */
  meta?: unknown;
  clientX?: number;
  clientY?: number;
};

export type SwimlaneItemClickedEvent = {
  target: SwimlaneTarget;
  span?: SwimlaneSpan;
  pending?: SwimlanePending;
  related?: string[];
  process?: string;
  /** For `target.kind === "step"`: every row belonging to that step. */
  steps?: SwimlaneRow[];
  /** See `SwimlaneHoverChangedEvent.meta`. */
  meta?: unknown;
};

export type SwimlaneEvents = {
  onHoverChanged: SwimlaneHoverChangedEvent;
  onItemClicked: SwimlaneItemClickedEvent;
};

// ─────────────────────────────────────────────────────────────────────────────
// Data-action payloads
// ─────────────────────────────────────────────────────────────────────────────

export type SwimlaneEventsReceivedEvent = {
  /** Which model to update (apps may show several swimlanes). */
  modelId: string;
  events: SwimlaneEvent[];
};

export type SwimlaneRowsClearedEvent = {
  modelId: string;
};

export const DEF_LANE_WIDTH = 104;
export const DEF_ROW_HEIGHT = 30;
export const DEF_HEADER_HEIGHT = 130;
export const DEF_GUTTER_WIDTH = 92;
export const DEF_MAX_ROWS = 2000;
